import{z as n,x as A,o as t,c as B,q as o,j as l,D as r,d as a,s as d,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"晶圆边缘排除区","description":"","frontmatter":{"title":"晶圆边缘排除区","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-edge-exclusion.md","filePath":"litho/wafer-edge-exclusion.md","lastUpdated":1791413859000}'),m={name:"litho/wafer-edge-exclusion.md"};function p(g,e,c,f,u,h){const i=A("Mermaid");return t(),B("div",null,[e[2]||(e[2]=o('<h1 id="晶圆边缘排除区" tabindex="-1">晶圆边缘排除区 <a class="header-anchor" href="#晶圆边缘排除区" aria-label="Permalink to &quot;晶圆边缘排除区&quot;">​</a></h1><div class="epigraph"><p>晶圆最外圈几毫米天生是坏地：边缘效应从光刻一路烧到封装——划出排除区，把良率数学先赢回来。</p><footer>—— 据 SEMI 晶圆规格边缘排除条款；各节点 fab 的 edge die 政策演变</footer></div><p><a href="/litho/mix-and-match-overlay">混合匹配与套刻拼接</a>提过「边缘损失顺手消化」，本课把边缘单独成课。缺口是<strong>边缘排除区（edge exclusion, EE）</strong>：晶圆直径的最外 1–3mm 不做图形。看似浪费，实则是全工艺链的良率契约。本课不做边缘 die 的 capture 概率细算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>边缘是物理上的重灾区：光刻的照明均匀性在晶圆边缘劣化（扫描曝光的场边缘效应）、CMP 的边缘失压（Pad 边缘力学）、传送与机械手的夹持痕（edge grip 区）、测试探针的边缘接触不良。在这些区域投片，die 的良率趋零但仍占曝光产能。缺口：<strong>在直径上划出排除环</strong>，让产能与计量资源集中在能活的区域。排除宽度是各节点的经济决策而非物理常数。</p><p><span class="marginnote">术语翻译：edge exclusion（EE）= 晶圆外缘不做工艺的环形区，宽度常 1–3mm；edge die = 场域中心落在排除区外的残缺 die；edge grip = 晶圆传送的机械夹持环，物理占用外缘。</span></p><p><span class="marginnote">数字实例：300mm 晶圆 EE=2mm 时可图形面积损失 π(R²−(R−2)²)≈18.7cm²，约 2.6% 面积；但这 18.5cm² 若不排除，其 die 良率近零且探针测试还会拖累测试产能——排除是「主动放弃换整体良率」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>排除区设定三输入：<strong>物理底线</strong>——edge grip 与装卸要求的机械占用；<strong>工艺极限</strong>——光刻照明的边缘均匀性、CMP 边缘失压、膜厚 edge roll-off 各自要求的宽度，取最大值；<strong>经济权衡</strong>——die 的 capture 概率（残缺 die 被计入良率的比例政策）与测试成本。执行上排除区写进每层工艺的 recipe，不靠设计者自觉；先进 fab 的 EE 已从历史 3mm 压到 1mm 级，每压缩 1mm 换回约 1.3% 的 die 产出。</p>',9)),(t(),l(s,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%89%A9%E7%90%86%3A%20edge%20grip%2F%E8%A3%85%E5%8D%B8%22%5D%20--%3E%20B%5B%22EE%20%E5%AE%BD%E5%BA%A6%E4%B8%8B%E9%99%90%22%5D%0A%20%20C%5B%22%E5%B7%A5%E8%89%BA%3A%20%E5%85%89%E5%88%BB%2FCMP%2F%E8%86%9C%E5%8E%9A%E8%BE%B9%E7%BC%98%E5%8A%A3%E5%8C%96%22%5D%20--%3E%20D%5B%22EE%20%E5%AE%BD%E5%BA%A6%E5%B7%A5%E8%89%BA%E9%A1%B9%22%5D%0A%20%20E%5B%22%E7%BB%8F%E6%B5%8E%3A%20capture%2F%E6%B5%8B%E8%AF%95%E6%88%90%E6%9C%AC%22%5D%20--%3E%20F%5B%22EE%20%E5%AE%BD%E5%BA%A6%E6%9D%83%E8%A1%A1%E9%A1%B9%22%5D%0A%20%20B%20--%3E%20G%5B%22%E5%8F%96%E6%9C%80%E5%A4%A7%20%E2%86%92%20%E5%88%92%E7%8E%AF%22%5D%0A%20%20D%20--%3E%20G%0A%20%20F%20--%3E%20G%0A%20%20G%20--%3E%20H%5B%22%E6%8E%92%E9%99%A4%E5%8C%BA%E5%A4%96%E6%8A%95%E7%89%87%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像农田边缘不种庄稼——田埂（edge grip）、水渠边上浇不匀（工艺边缘劣化）、收割机够不到（测试），与其撒了种子收瘪谷，不如留成路；但田埂也别太宽，多留一寸就少收一垄。")],-1)),e[4]||(e[4]=E("h2",{id:"机制",tabindex:"-1"},[a("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=E("p",null,[a("边缘劣化的机制各层不同但同向。光刻：扫描曝光中狭缝照明的场边缘强度滚降 + 晶圆边缘的聚焦/平整度劣化（edge roll-off 数百纳米），CD 与叠加套刻在边缘双双恶化。CMP：抛光垫在晶圆边缘的接触力学突变（边缘气穴与垫形变），去除速率偏离中心——不排除则边缘层厚失配污染叠层。测试：边缘 die 的针测接触不稳，坏 contact 会误判好 die。机制的共同点："),E("strong",null,"边缘效应以毫米尺度缓变"),a("，故排除区宽度是「够用即可」的阶跃决策，而非连续优化；难点在各环节极值不同，取包络后可能过排除——分层 EE（不同工艺不同宽度）是折衷。")],-1)),(t(),l(s,null,{default:r(()=>[d(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%BE%B9%E7%BC%98%E4%B8%BA%E4%BD%95%E7%83%82%3F%22%7D%20--%3E%7C%22%E5%85%89%E5%88%BB%22%7C%20R%5B%22%E7%85%A7%E6%98%8E%E6%BB%9A%E9%99%8D%20%2B%20edge%20roll-off%22%5D%0A%20%20Q%20--%3E%7C%22CMP%22%7C%20S%5B%22%E8%BE%B9%E7%BC%98%E5%A4%B1%E5%8E%8B%2C%20%E5%8E%BB%E9%99%A4%E7%8E%87%E5%81%8F%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B5%8B%E8%AF%95%22%7C%20T%5B%22%E9%92%88%E6%B5%8B%E6%8E%A5%E8%A7%A6%E4%B8%8D%E7%A8%B3%22%5D%0A%20%20R%20--%3E%20U%5B%22%E5%90%84%E7%8E%AF%E8%8A%82%E5%8A%A3%E5%8C%96%E5%AE%BD%E5%BA%A6%E4%B8%8D%E5%90%8C%22%5D%0A%20%20S%20--%3E%20U%0A%20%20T%20--%3E%20U%0A%20%20U%20--%3E%20V%5B%22%E5%88%86%E5%B1%82%20EE%3A%20%E5%90%84%E8%87%AA%E5%A4%9F%E7%94%A8%E5%8D%B3%E5%8F%AF%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<p><span class="marginnote">常见误区：把 EE 宽度当 fab 常数一刀切到底——光刻 2mm 可能已稳，CMP 却要 3mm，统一 3mm 就是白扔 1mm 的 die；另一误区是「排除区绝对不碰」——edge die 的 capture 政策（残缺 die 是否测试计产）与 EE 宽度是一体两面的经济决策，二者须一起谈。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>EE 与先进封装的新纠缠：chiplet 时代晶圆边缘的 die 价值升高（小 die 在边缘 capture 率高），压缩 EE 的经济动力增强；对面板级封装（PLP）用方形基板，圆晶圆的边缘数学整体消失。工艺侧：edge bead removal（旋涂去边）、边缘曝光（edge exposure）是「在排除区内也要处理干净」的配套——排除的是「做产品」，不是「不做任何事」，边缘残留光刻胶会污染后续工艺。与<a href="/litho/euv-dose-budget">EUV 剂量预算</a>的接续：排除区收缩后，照明边缘的剂量控制余量变小——边缘的剂量漂移成为 EE 能压多窄的隐形下限。</p><p><span class="marginnote">直觉类比：压缩 EE 像「把田埂改窄」——改造的是收割机（更贴边的计量与传送），不是把庄稼种进田埂；每一毫米的收复都要先确认水渠、田埂、收割机三方面都真的让得出来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EE = 物理占用 + 工艺边缘劣化 + 经济权衡的包络，是阶跃决策。</li><li>光刻滚降、CMP 失压、针测不稳三机制同向，宽度取最大。</li><li>chiplet 抬高边缘 die 价值，EE 从 3mm 向 1mm 收缩是趋势。</li><li>出处：SEMI 晶圆规格；edge roll-off 计量文献；fab edge die 政策实践。</li></ul>',6))])}const _=n(m,[["render",p]]);export{C as __pageData,_ as default};
